typedef unsigned int u_int;

template <int n> struct SplineCoeffs {
	float a[n], b[n], c[n], d[n];
};

typedef struct {
	SplineCoeffs<16> y, z;
} WaveProfileCoeffs;

struct WaveControlPoints {
	char data[0x2400];
	u_int numcontrol, numprofile;
};

extern float WAVE_ControlZ[16];
extern WaveControlPoints *WAVE_ControlPoints;
extern "C" void sceVu0Normalize(float *, const float *);

inline u_int SPLINE_BinarySearch(const float *x, u_int n, const float &valx)
{
	u_int lo = 0, hi = n - 1, mid;
	while (hi - lo > 1)
	{
		mid = (lo + hi) / 2;
		if (x[mid] < valx) lo = mid;
		else hi = mid;
	}

	return lo;
}

inline float SPLINE_EvaluateD(const float *x, const float *a, const float *b, const float *c, const float *d,
	u_int n, float valx)
{
	u_int lo = SPLINE_BinarySearch(x, n, valx);
	valx -= x[lo];
	return (3 * a[lo] * valx + 2 * b[lo]) * valx + c[lo];
}

inline void KSNGL_Normalize(float *n)
{
	sceVu0Normalize(n, n);
}

void WAVE_Normal(const WaveProfileCoeffs &wpc, float z, float &nx, float &ny, float &nz)
{
	u_int zhint = SPLINE_BinarySearch(WAVE_ControlZ, WAVE_ControlPoints->numcontrol, z);
	float dyy_dz, dzz_dz;

	dyy_dz = SPLINE_EvaluateD(WAVE_ControlZ, wpc.y.a, wpc.y.b, wpc.y.c, wpc.y.d, WAVE_ControlPoints->numcontrol, z, zhint);
	dzz_dz = SPLINE_EvaluateD(WAVE_ControlZ, wpc.z.a, wpc.z.b, wpc.z.c, wpc.z.d, WAVE_ControlPoints->numcontrol, z, zhint);

	nx = 0;
	ny = dzz_dz;
	nz = -dyy_dz;

	KSNGL_Normalize((float *) &nx);
}
